StructuredTextModel.Text:
(*
				QUICK DESCRIPTION OF THE PURPOSE OF THE FUNCTION BLOCK
				developed for PROJECT NAME
				
				Author: ##@cobod.com 
				
				REVISIONS:
				V1.0.0		-		YYYY-MM-DD		-		INITIALS		-		CHANGE LOG
				
				
				ERROR IDs:
				99000		-		unknown FB step

*)

// - - - - - - - - - - - - - - - - - - - - INPUT EDGE DETECTION
Execute_RE(Clk:=Execute);
Execute_FE(Clk:=Execute);


// - - - - - - - - - - - - - - - - - - - - START AND STOP OF FB
IF Execute_RE.Q AND NOT Busy THEN
	// set busy flag
	Busy:=TRUE;
	// start homing sequence
	fbStep:=10;
END_IF;

IF Execute_FE.Q AND Busy THEN
	// cancel active sequence
	fbStep:=800;
ELSIF Execute_FE.Q AND NOT Busy THEN
	// reset FB
	fbStep:=900;
END_IF;


// - - - - - - - - - - - - - - - - - - - - MAIN CODE CASE
CASE fbStep OF 
	
	// - - - - - - -   CASE 000: IDLE   - - - - - - - //
	0: // idle
		fbStep:=0;
	
	
	// - - - - - - -   CASE 010: INITIALISE   - - - - - - - //
	10: // initialise FB
		
		// reset ErrorID
		ErrorID:=0;
		
	// - - - - - - -   CASE 800: STOP FB   - - - - - - - //
	800: // stop functions in controlled way and prep for reset
		
		fbStep:=900;
		
	// - - - - - - -   CASE 900: RESET FB   - - - - - - - //
	900: // clear up and prepare for next execution
	
		Busy:=FALSE;
		Done:=FALSE;
		Error:=FALSE;
	
ELSE
		Error:=TRUE;
		ErrorID:=99000;	// ERROR: unknown FB step		
END_CASE;


// - - - - - - - - - - - - - - - - - - - - refresh FBs


// - - - - - - - - - - - - - - - - - - - - FB ERROR HANDLING


// - - - - - - - - - - - - - - - - - - - - CLEAR BUSY FLAG
IF Error THEN
		Busy:=FALSE;
END_IF;


// - - - - - - - - - - - - - - - - - - - - FB StateID
StateID:=fbStep;
